@RunWith(AndroidJUnit4::class)
class HomeUITest {
    @get:Rule val rule = createAndroidComposeRule<MainActivity>()

    @After fun restoreOrientation() {
        rule.activityRule.scenario.onActivity { it.requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED }
    }

    private fun isTablet() = rule.activity.resources.configuration.smallestScreenWidthDp >= 600

    // region HomeScreen

    // uitest: HomeScreen | - 공통: `home.screen` 과 `home.newJournalButton` 이 보인다
    @Test fun test_HomeScreen_showsScreenAndNewJournalButton() {
        rule.onNodeWithTag(TestTags.Home.SCREEN, useUnmergedTree = true).assertIsDisplayed()
        rule.onNodeWithTag(TestTags.Home.NEW_JOURNAL_BUTTON, useUnmergedTree = true).assertIsDisplayed()
    }

    // uitest: HomeScreen | - 폰 가로로 돌리면: `home.screen` 과 `home.newJournalButton` 이 그대로 보인다
    @Test fun test_HomeScreen_phoneLandscapeKeepsScreenAndNewJournalButton() {
        Assume.assumeFalse("폰 전용", isTablet())
        rule.onNodeWithTag(TestTags.Home.SCREEN, useUnmergedTree = true).assertIsDisplayed()
        rule.activityRule.scenario.onActivity { it.requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE }
        rule.waitForIdle()
        rule.onNodeWithTag(TestTags.Home.SCREEN, useUnmergedTree = true).assertIsDisplayed()
        rule.onNodeWithTag(TestTags.Home.NEW_JOURNAL_BUTTON, useUnmergedTree = true).assertIsDisplayed()
    }

